import React, { useEffect, useState } from "react";
import { ChevronDown, Menu, X, Phone } from "lucide-react";
import { brand, topLinks, nav } from "../mock";
import { pageHref } from "../lib/navigation";
import QuoteDialog from "./QuoteDialog";

const OLIVE = "#6b7a35";
const CHARCOAL = "#2f2e2a";
const logoSrc = `${process.env.PUBLIC_URL || ""}/images/blikas-olives-logo.png`;

export default function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [openIdx, setOpenIdx] = useState(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const Logo = (
    <a href="#/" className="flex items-center gap-3 group" aria-label="Blikas Olives - Αρχική">
      <img
        src={logoSrc}
        alt="Blikas Olives"
        className="h-16 w-16 shrink-0 rounded-md object-cover shadow-sm ring-1 ring-black/5 transition-transform duration-300 group-hover:-rotate-2 group-hover:scale-[1.03]"
      />
      <div className="leading-none">
        <div className="font-display text-[25px] font-700" style={{ color: CHARCOAL }}>
          {brand.name} <span style={{ color: OLIVE }}>{brand.suffix}</span>
        </div>
        <div className="text-[12px] tracking-[0.16em] text-neutral-500 uppercase">
          {brand.tagline}
        </div>
      </div>
    </a>
  );

  return (
    <header className="sticky top-0 z-50">
      {/* Top utility bar */}
      <div style={{ background: CHARCOAL }} className="text-neutral-300 text-[14px] hidden md:block">
        <div className="max-w-[1440px] mx-auto px-8 flex items-center justify-between h-10">
          <div className="flex items-center gap-5">
            {topLinks.left.map((l) => (
              <a key={l.label} href={pageHref(l.href)} className="hover:text-white transition-colors">
                {l.label}
              </a>
            ))}
          </div>
          <div className="flex items-center gap-5">
            {topLinks.right.map((l) => (
              <a key={l.label} href={pageHref(l.href)} className="hover:text-white transition-colors">
                {l.label}
              </a>
            ))}
            <span className="text-neutral-500">|</span>
            <button className="hover:text-white transition-colors">EN</button>
            <button className="text-neutral-500 hover:text-white transition-colors">GR</button>
          </div>
        </div>
      </div>

      {/* Main nav */}
      <div className={`bg-white transition-shadow duration-300 ${scrolled ? "shadow-lg" : "shadow-sm"}`}>
        <div className="max-w-[1440px] mx-auto px-5 md:px-8 flex items-center justify-between h-[88px]">
          {Logo}

          <nav className="hidden xl:flex items-center gap-0.5">
            {nav.map((item, i) => (
              <div
                key={item.label}
                className="relative"
                onMouseEnter={() => setOpenIdx(i)}
                onMouseLeave={() => setOpenIdx(null)}
              >
                <a
                  href={pageHref(item.href)}
                  className="font-display text-[17px] leading-none whitespace-nowrap tracking-wide px-2.5 2xl:px-3.5 py-8 flex items-center gap-1 text-neutral-700 hover:text-[#6b7a35] transition-colors"
                >
                  {item.label}
                  {item.children && <ChevronDown size={14} className="mt-[2px]" />}
                </a>
                {item.children && openIdx === i && (
                  <div className="absolute left-0 top-full min-w-[250px] bg-white shadow-2xl border-t-2 border-[#6b7a35] py-2 rounded-b-md">
                    {item.children.map((c) => (
                      <a
                        key={c.label}
                        href={pageHref(c.href)}
                        className="block px-5 py-3 text-[15px] text-neutral-700 hover:bg-[#f2f4e8] hover:text-[#6b7a35] transition-colors"
                      >
                        {c.label}
                      </a>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </nav>

          <div className="hidden xl:block">
            <QuoteDialog
              trigger={
                <button
                  className="font-display whitespace-nowrap tracking-wider text-[16px] text-white px-6 py-3.5 shadow-sm transition-all hover:-translate-y-0.5 hover:shadow-lg"
                  style={{ background: OLIVE }}
                >
                  ΖΗΤΗΣΤΕ ΠΡΟΣΦΟΡΑ
                </button>
              }
            />
          </div>

          <button
            className="xl:hidden text-neutral-800 p-2 -mr-2 rounded-md hover:bg-[#f2f4e8] transition-colors"
            onClick={() => setMobileOpen((o) => !o)}
            aria-label="menu"
          >
            {mobileOpen ? <X size={26} /> : <Menu size={26} />}
          </button>
        </div>

        {/* Mobile menu */}
        {mobileOpen && (
          <div className="xl:hidden border-t border-neutral-100 bg-white shadow-lg">
            <div className="px-6 py-4 flex flex-col">
              {nav.map((item) => (
                <a
                  key={item.label}
                  href={pageHref(item.href)}
                  onClick={() => setMobileOpen(false)}
                  className="font-display text-[18px] py-4 border-b border-neutral-100 text-neutral-700 hover:text-[#6b7a35] transition-colors"
                >
                  {item.label}
                </a>
              ))}
              <div className="py-4 flex items-center gap-2 text-[15px] text-neutral-600">
                <Phone size={16} style={{ color: OLIVE }} /> +30 2310 000 000
              </div>
              <QuoteDialog
                trigger={
                  <button
                    className="font-display tracking-wider text-[16px] text-white px-6 py-3.5 w-full shadow-sm"
                    style={{ background: OLIVE }}
                  >
                    ΖΗΤΗΣΤΕ ΠΡΟΣΦΟΡΑ
                  </button>
                }
              />
            </div>
          </div>
        )}
      </div>
    </header>
  );
}
