import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from "./ui/dialog";
import { Input } from "./ui/input";
import { Label } from "./ui/label";
import { Textarea } from "./ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "./ui/select";
import { toast } from "sonner";

const OLIVE = "#6b7a35";

export default function QuoteDialog({ trigger }) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: "", email: "", type: "", message: "" });

  const submit = (e) => {
    e.preventDefault();
    if (!form.name || !form.email) {
      toast.error("Συμπληρώστε το όνομα και το email σας.");
      return;
    }
    // Mock submission (frontend only)
    const saved = JSON.parse(localStorage.getItem("blikas_quotes") || "[]");
    saved.push({ ...form, at: new Date().toISOString() });
    localStorage.setItem("blikas_quotes", JSON.stringify(saved));
    toast.success("Ευχαριστούμε! Η ομάδα μας θα επικοινωνήσει σύντομα μαζί σας.");
    setForm({ name: "", email: "", type: "", message: "" });
    setOpen(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>{trigger}</DialogTrigger>
      <DialogContent className="sm:max-w-[480px]">
        <DialogHeader>
          <DialogTitle className="font-display text-2xl tracking-wide">
            Ζητήστε προσφορά
          </DialogTitle>
          <p className="text-sm text-neutral-500">
            Πείτε μας τι χρειάζεστε — χονδρική ή λιανική — και θα επικοινωνήσουμε μαζί σας.
          </p>
        </DialogHeader>
        <form onSubmit={submit} className="space-y-4 pt-2">
          <div className="space-y-1.5">
            <Label htmlFor="q-name">Ονοματεπώνυμο</Label>
            <Input
              id="q-name"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              placeholder="Το όνομά σας"
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="q-email">Email</Label>
            <Input
              id="q-email"
              type="email"
              value={form.email}
              onChange={(e) => setForm({ ...form, email: e.target.value })}
              placeholder="you@example.com"
            />
          </div>
          <div className="space-y-1.5">
            <Label>Ενδιαφέρομαι για</Label>
            <Select value={form.type} onValueChange={(v) => setForm({ ...form, type: v })}>
              <SelectTrigger>
                <SelectValue placeholder="Επιλέξτε" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="retail">Λιανική / προσωπική παραγγελία</SelectItem>
                <SelectItem value="wholesale">Χονδρική / διανομή</SelectItem>
                <SelectItem value="foodservice">Μαζική εστίαση / HoReCa</SelectItem>
                <SelectItem value="private-label">Ιδιωτική ετικέτα</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="q-msg">Μήνυμα</Label>
            <Textarea
              id="q-msg"
              value={form.message}
              onChange={(e) => setForm({ ...form, message: e.target.value })}
              placeholder="Ποια προϊόντα και ποσότητες σας ενδιαφέρουν;"
              rows={3}
            />
          </div>
          <DialogFooter>
            <button
              type="submit"
              className="font-display tracking-wider text-white px-6 py-3 w-full transition-transform hover:-translate-y-0.5"
              style={{ background: OLIVE }}
            >
              ΑΠΟΣΤΟΛΗ ΑΙΤΗΜΑΤΟΣ
            </button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}
