import React from "react";
import { audience } from "../mock";
import QuoteDialog from "./QuoteDialog";
import { pageHref } from "../lib/navigation";

const OLIVE = "#6b7a35";

function Btn({ b }) {
  if (b.variant === "solid") {
    return (
      <a
        href={pageHref(b.href)}
        className="font-display tracking-wider text-[13px] px-5 py-3 text-white text-center transition-transform hover:-translate-y-0.5"
        style={{ background: OLIVE }}
      >
        {b.label}
      </a>
    );
  }
  return (
    <a
      href={b.href}
      className="font-display tracking-wider text-[13px] px-5 py-3 text-center border transition-colors hover:bg-[#f2f4e8]"
      style={{ borderColor: OLIVE, color: OLIVE }}
    >
      {b.label}
    </a>
  );
}

export default function AudienceSplit() {
  return (
    <section id="audience" className="bg-white pb-16 lg:pb-24">
      <div className="max-w-[1120px] mx-auto px-6 grid md:grid-cols-2 gap-8 lg:gap-12">
        {audience.map((a) => (
          <div key={a.key} className="reveal">
            <div
              className="badge-skew inline-block px-8 py-2.5 mb-[-6px] relative z-10"
              style={{ background: OLIVE }}
            >
              <span className="font-display text-white tracking-wider text-lg">
                {a.badge}
              </span>
            </div>
            <div className="overflow-hidden">
              <img
                src={a.image}
                alt={a.badge}
                className="w-full h-[240px] object-cover transition-transform duration-700 hover:scale-105"
              />
            </div>
            <p className="text-neutral-600 text-[15px] leading-relaxed my-6">
              {a.text}
            </p>
            <div className="grid grid-cols-2 gap-3">
              {a.buttons.map((b) =>
                b.variant === "solid" ? (
                  <QuoteDialog
                    key={b.label}
                    trigger={
                      <button
                        className="font-display tracking-wider text-[13px] px-5 py-3 text-white w-full transition-transform hover:-translate-y-0.5"
                        style={{ background: OLIVE }}
                      >
                        {b.label}
                      </button>
                    }
                  />
                ) : (
                  <Btn key={b.label} b={b} />
                )
              )}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
