import React, { useEffect, useRef, useState } from "react";
import { stats } from "../mock";
import QuoteDialog from "./QuoteDialog";

const BG = "https://images.pexels.com/photos/11086294/pexels-photo-11086294.jpeg";

function useCountUp(target, run) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!run) return;
    let raf;
    const dur = 1600;
    const start = performance.now();
    const tick = (now) => {
      const p = Math.min((now - start) / dur, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      setVal(Math.floor(eased * target));
      if (p < 1) raf = requestAnimationFrame(tick);
      else setVal(target);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [run, target]);
  return val;
}

function Stat({ item, run }) {
  const v = useCountUp(item.value, run);
  return (
    <div className="text-center">
      <div className="font-display text-white text-4xl lg:text-[52px] leading-none">
        {v.toLocaleString()}
        {item.suffix}
      </div>
      <div className="text-white/75 text-sm mt-2 tracking-wide uppercase">
        {item.label}
      </div>
    </div>
  );
}

export default function StatsBand() {
  const ref = useRef(null);
  const [run, setRun] = useState(false);

  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setRun(true);
          obs.disconnect();
        }
      },
      { threshold: 0.3 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section ref={ref} className="relative py-20 lg:py-28">
      <div className="absolute inset-0">
        <img src={BG} alt="olive grove" className="w-full h-full object-cover" />
        <div className="absolute inset-0" style={{ background: "rgba(45,50,25,0.82)" }} />
      </div>
      <div className="relative max-w-[1100px] mx-auto px-6">
        <h2 className="font-display text-white text-center text-3xl lg:text-[40px] tracking-wide mb-14">
          Καλλιεργούμε ελιές που απολαμβάνει ο κόσμος
        </h2>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-10 mb-14">
          {stats.map((s) => (
            <Stat key={s.label} item={s} run={run} />
          ))}
        </div>
        <div className="text-center">
          <QuoteDialog
            trigger={
              <button className="font-display tracking-wider text-sm px-8 py-3.5 bg-white text-[#3d4620] hover:bg-neutral-100 transition-colors">
                ΖΗΤΗΣΤΕ ΔΩΡΕΑΝ ΠΡΟΣΦΟΡΑ
              </button>
            }
          />
        </div>
      </div>
    </section>
  );
}
